from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework.exceptions import PermissionDenied, NotFound
from rest_framework import status
from waffle.models import Flag

ALLOWED_SELF_ENROLL_FLAGS = {'new_dashboard_v2', 'dark_mode_beta', 'compact_table_view'}

class FeatureFlagSelfEnrollView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, flag_name: str):
        if flag_name not in ALLOWED_SELF_ENROLL_FLAGS:
            raise PermissionDenied("This feature flag is not open for self-enrollment")

        try:
            flag = Flag.objects.get(name=flag_name)
        except Flag.DoesNotExist:
            raise NotFound("Feature flag not found")

        flag.users.add(request.user)
        return Response({'status': 'enrolled', 'flag': flag.name, 'user': request.user.username})
